Object.assign(text.ru,{openSheet:'Открыть лист',linksLabel:'Инструменты ведущего',lkMarket:'Ночной рынок',lkClocks:'Часы',lkTables:'Таблицы',lkWeather:'Погода',lkNpcs:'Библиотека NPC',journal:'ЖУРНАЛ',journalHelp:'Хроника кампании: свои записи и автоматические отметки о ходе боя.',journalPh:'Что произошло…',journalAdd:'Записать',journalEmpty:'Записей пока нет.',journalDel:'Удалить запись',journalAuto:'авто',journalExport:'Экспорт в Markdown',journalAutoRoll:n=>`Брошена инициатива для всех (участников: ${n})`,journalAutoRound:n=>`Начался раунд ${n}`,journalAutoReset:'Бой сброшен',journalTitle:'Журнал'});
Object.assign(text.en,{openSheet:'Open sheet',linksLabel:'GM tools',lkMarket:'Night Market',lkClocks:'Clocks',lkTables:'Tables',lkWeather:'Weather',lkNpcs:'NPC library',journal:'JOURNAL',journalHelp:'Campaign log: your own entries plus automatic marks for combat progress.',journalPh:'What happened…',journalAdd:'Add entry',journalEmpty:'No entries yet.',journalDel:'Delete entry',journalAuto:'auto',journalExport:'Export to Markdown',journalAutoRoll:n=>`Initiative rolled for everyone (combatants: ${n})`,journalAutoRound:n=>`Round ${n} started`,journalAutoReset:'Combat reset',journalTitle:'Journal'});
const JOURNAL_MAX=300;
function readJournal(c){const raw=c&&Array.isArray(c.journal)?c.journal:[],out=[];for(const x of raw){if(!x||typeof x!=='object'||Array.isArray(x))continue;const text=typeof x.text==='string'?x.text.replace(/\u0000/g,'').slice(0,2000):'';if(!text.trim())continue;const at=Number(x.at);out.push({id:typeof x.id==='string'&&x.id&&x.id.length<=160?x.id:'j'+out.length+'-'+(Number.isFinite(at)?at:0),at:Number.isFinite(at)?at:0,text,auto:x.auto===true});if(out.length>=JOURNAL_MAX)break}return out}
function journalAdd(c,textValue,auto,now=Date.now(),id){const clean=typeof textValue==='string'?textValue.replace(/\u0000/g,'').trim().slice(0,2000):'';if(!c||typeof c!=='object'||!clean)return false;const list=readJournal(c);list.unshift({id:id||uid(),at:now,text:clean,auto:!!auto});c.journal=list.slice(0,JOURNAL_MAX);return true}
function pad2(n){return String(n).padStart(2,'0')}
function stamp(at){const d=new Date(at);return isNaN(d)?'':`${d.getFullYear()}-${pad2(d.getMonth()+1)}-${pad2(d.getDate())} ${pad2(d.getHours())}:${pad2(d.getMinutes())}`}
function journalMarkdown(c,lang){const t=text[lang==='en'?'en':'ru'],list=readJournal(c).slice().reverse();let out=`# ${String(c?.name||'').replace(/[\r\n]+/g,' ').trim()||t.unknown} — ${t.journalTitle}\n\n`;if(!list.length)return out+`_${t.journalEmpty}_\n`;for(const e of list)out+=`- **${stamp(e.at)}**${e.auto?` _(${t.journalAuto})_`:''} — ${e.text.replace(/\r/g,'').replace(/\n+/g,'\n  ')}\n`;return out}
function journalFile(c){return (String(c?.name||'').replace(/[^\p{L}\p{N}]+/gu,'-').replace(/^-+|-+$/g,'').slice(0,40)||'campaign')+'-journal.md'}
function downloadText(name,body){try{const url=URL.createObjectURL(new Blob([body],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);return true}catch{return false}}
function journalHTML(c,t){const list=readJournal(c),draft=formDraft(c.id).journal||'';return `<section class="card camp-journal" data-campaign-journal><div class="card-heading"><span>${t.journal}</span><span>${list.length} / ${JOURNAL_MAX}</span></div><p class="muted">${t.journalHelp}</p><div class="jr-add"><textarea id="campaign-journal-text" rows="2" maxlength="2000" placeholder="${esc(t.journalPh)}">${draft?'\n'+esc(draft):''}</textarea><div class="campaign-controls" style="margin:0"><button class="btn primary" data-campaign-action="journal-add">＋ ${t.journalAdd}</button><button class="btn ghost" data-campaign-action="journal-export" ${!list.length?'disabled':''}>⬇ ${t.journalExport}</button></div></div><div class="jr-list">${list.length?list.map(e=>`<div class="jr-entry${e.auto?' auto':''}"><time>${esc(stamp(e.at))}${e.auto?`<span class="jr-tag">${t.journalAuto}</span>`:''}</time><p>${esc(e.text)}</p><button class="skill-roll" data-campaign-action="journal-del" data-id="${esc(e.id)}" aria-label="${t.journalDel}" title="${t.journalDel}">✕</button></div>`).join(''):`<p class="muted">${t.journalEmpty}</p>`}</div></section>`}
function linksHTML(t){return `<div class="camp-links" data-campaign-links><span class="camp-links-label">${t.linksLabel}</span>${[['market',t.lkMarket],['clocks',t.lkClocks],['tables',t.lkTables],['weather',t.lkWeather],['npcs',t.lkNpcs]].map(([k,l])=>`<button class="btn ghost" data-campaign-action="goto-gm" data-section="${k}">${l} ↗</button>`).join('')}</div>`}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>globalThis.crypto?.randomUUID?.()||Date.now()+'-'+Math.random().toString(36).slice(2);
function npcTemplates(){
 const rows=window.GMTools?.NPC_TEMPLATES;if(!Array.isArray(rows))return [];
 const ids=new Map();for(const row of rows)if(row&&typeof row.id==='string')ids.set(row.id,(ids.get(row.id)||0)+1);
 return rows.filter(row=>row&&typeof row==='object'&&!Array.isArray(row)&&typeof row.id==='string'&&!!row.id.trim()&&row.id.length<=160&&ids.get(row.id)===1&&row.name&&typeof row.name==='object'&&['ru','en'].every(l=>typeof row.name[l]==='string'&&!!row.name[l].trim()&&row.name[l].length<=100)&&Number.isSafeInteger(row.stats?.REF)&&row.stats.REF>=0&&row.stats.REF<=20&&Number.isSafeInteger(row.hp)&&row.hp>=0&&row.hp<=999&&Number.isSafeInteger(row.page)&&row.page>=1&&row.page<=999);
}
// A lone NPC keeps the plain book name. With company every copy gets a number, continuing after the highest one in use.
function templateNames(base,count,roster){
 const b=String(base).slice(0,96),re=new RegExp('^'+b.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?: (\\d+))?$');let max=0,same=0;
 for(const r of Array.isArray(roster)?roster:[]){const m=r?.kind==='npc'&&typeof r.name==='string'?re.exec(r.name):null;if(m){same++;max=Math.max(max,Number(m[1])||1)}}
 if(count===1&&!same)return [b];
 return Array.from({length:count},(_,i)=>`${b} ${max+i+1}`);
}
// The armor and weapons of a book template, for the combatant note.
function templateNote(template){
 const parts=[],a=template?.armor,sp=x=>Number.isSafeInteger(x)&&x>=0&&x<=99;
 if(a&&typeof a==='object'&&sp(a.headSP)&&sp(a.bodySP))parts.push(`SP ${a.headSP}/${a.bodySP}`);
 const weapons=(Array.isArray(template?.weapons)?template.weapons:[]).filter(w=>w&&typeof w.name==='string'&&typeof w.damage==='string').map(w=>`${w.name} ${w.damage}`).join('; ');
 if(weapons)parts.push(weapons);
 return parts.join(' · ').replace(/\s+/g,' ').slice(0,300);
}
// Adds `count` copies of a book template to a campaign roster: numbered names, the armor-and-weapons note.
function addTemplates(campaign,templateId,count,lang,firstId){
 const matches=npcTemplates().filter(x=>x.id===templateId),template=matches.length===1?matches[0]:null,l=lang==='en'?'en':'ru';
 const n=Number.isSafeInteger(count)?Math.max(1,Math.min(20,count)):1;
 if(!template||!campaign||!Array.isArray(campaign.roster)||campaign.roster.length+n>2045)return {ok:false,added:[]};
 const names=templateNames(template.name[l].trim(),n,campaign.roster),note=templateNote(template),now=Date.now(),added=[];
 names.forEach((name,i)=>{const row={id:i||!firstId?uid():firstId,kind:'npc',name,ref:template.stats.REF,hp:template.hp,maxHp:template.hp,initiative:0,order:now+i,sourceTemplate:template.id,sourcePage:template.page};
  const a=template.armor,okSp=x=>Number.isSafeInteger(x)&&x>=0&&x<=30;if(a&&okSp(a.headSP)&&okSp(a.bodySP))row.sp={head:a.headSP,body:a.bodySP};if(Number.isSafeInteger(template.stats?.BODY)&&template.stats.BODY>0)row.body=template.stats.BODY;if(note)row.combatNote={version:1,text:note};campaign.roster.push(row);added.push(row)});
 return {ok:true,added,name:template.name[l].trim()};
}
function npcTemplateHTML(lang){const t=text[lang],rows=npcTemplates();if(!rows.length)return '';return `<section class="card" data-campaign-template-root><div class="card-heading"><span>${esc(t.npcTemplate)}</span><span>COREBOOK</span></div><p class="muted">${esc(t.npcTemplateHelp)}</p><label class="field">${esc(t.npcTemplateChoose)}<select data-campaign-template><option value="">${esc(t.npcTemplateChoose)}</option>${rows.map(r=>`<option value="${esc(r.id)}">${esc(r.name[lang])} · ${esc(t.npcTemplateSource)} ${r.page}</option>`).join('')}</select></label><label class="field">${esc(t.npcTemplateCount)}<input type="number" inputmode="numeric" data-campaign-template-count min="1" max="10" step="1" value="1"></label><button class="btn ghost wide" type="button" data-campaign-action="add-template">＋ ${esc(t.npcTemplateAdd)}</button></section>`}
